def solve(n, edges):
    # Initialize parent array for Union-Find (Disjoint Set Union)
    parent = list(range(n))

    # Find function with path compression
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    # Union function
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    # Process each edge and perform union
    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    root_count = set()
    for i in range(n):
        root_count.add(find(i))

    return len(root_count)

def solve(n, edges):
    def dfs(node, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor, visited)

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    components = 0

    for node in range(n):
        if node not in visited:
            dfs(node, visited)
            components += 1

    return components

