class Solution:
    def __init__(self):
        self.parent = {}

    def find(self, x):
        if x not in self.parent:
            self.parent[x] = x
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y

    def get_parent(self, x):
        return self.parent.get(x, None)

    def is_connected(self, x, y):
        if x not in self.parent or y not in self.parent:
            return False
        return self.find(x) == self.find(y)

    def is_cycle(self, x, y):
        if x not in self.parent or y not in self.parent:
            return False
        root_x = self.find(x)
        return self.find(y) == root_x

    def solve(self, n, edges):
        # Initialize parent map
        self.parent = {}
        for i in range(n):
            self.parent[i] = i

        for u, v in edges:
            root_u = self.find(u)
            root_v = self.find(v)
            if root_u == root_v:
                # Cycle detected
                return False

        return True

