from typing import List

def solve(n: int, edges: List[List[int]]) -> int:
    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                for neighbor in range(n):
                    if not visited[neighbor] and any(edge == [node, neighbor] or edge == [neighbor, node] for edge in edges):
                        visited[neighbor] = True
